source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def ray(r, c, dr, dc, color):
        while 0 <= r < h and 0 <= c < w and grid[r][c] in (background, color):
            if grid[r][c] == background:
                out[r][c] = color
            r += dr
            c += dc

    # A 0 marks the junction of a bent set of rays.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if markers:
        for r, c in markers:
            if r >= 2 and c >= 1 and grid[r-2][c-1] == 3:
                ray(r-3, c-2, -1, -1, 3)
            if r+1 < h and c >= 1 and grid[r+1][c-1] == 3:
                ray(r+2, c-2, 1, -1, 3)
            if r >= 2 and c+2 < w and grid[r-2][c+2] == 4:
                ray(r-3, c+3, -1, 1, 4)
        return out

    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color:
                    flank_a = (r, c + dc)
                    flank_b = (r + dr, c)
                    enclosed = all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] != background
                                   for rr, cc in (flank_a, flank_b))
                    if not enclosed:
                        pairs.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in pairs:
        ray(r - dr, c - dc, -dr, -dc, color)
        ray(r + 2*dr, c + 2*dc, dr, dc, color)
    return out
'''
